#include <WiFi.h>
#include <WebServer.h>

const char* ssid     = "DEIN_WLAN";
const char* password = "DEIN_PASSWORT";

#define LED_PIN 25

WebServer server(80);

String buildPage(bool ledOn) {
  String page = "<!DOCTYPE html><html><head>";
  page += "<meta charset='utf-8'>";
  page += "<meta name='viewport' content='width=device-width,initial-scale=1'>";
  page += "<title>ESP32 LED</title></head><body>";
  page += "<h1>LED-Steuerung</h1>";
  page += "<p>Status: <b>";
  page += ledOn ? "AN" : "AUS";
  page += "</b></p>";
  page += "<a href='/on'><button>AN</button></a>  ";
  page += "<a href='/off'><button>AUS</button></a>";
  page += "</body></html>";
  return page;
}

void handleRoot() {
  bool state = digitalRead(LED_PIN);
  server.send(200, "text/html", buildPage(state));
}

void handleOn() {
  digitalWrite(LED_PIN, HIGH);
  server.send(200, "text/html", buildPage(true));
}

void handleOff() {
  digitalWrite(LED_PIN, LOW);
  server.send(200, "text/html", buildPage(false));
}

void setup() {
  Serial.begin(115200);
  pinMode(LED_PIN, OUTPUT);
  digitalWrite(LED_PIN, LOW);

  WiFi.begin(ssid, password);
  Serial.print("Verbinde mit WLAN");
  while (WiFi.status() != WL_CONNECTED) {
    delay(500);
    Serial.print(".");
  }
  Serial.println();
  Serial.print("IP-Adresse: ");
  Serial.println(WiFi.localIP());

  server.on("/",    handleRoot);
  server.on("/on",  handleOn);
  server.on("/off", handleOff);
  server.begin();
  Serial.println("Webserver gestartet!");
}

void loop() {
  server.handleClient();
}
